        private static byte[] s_gray16;

        /// <summary>Every 16-bit grey sample as the byte WIC converts it to.</summary>
        internal static byte[] Gray16 => s_gray16 ??= BuildGray16 ();

        private static byte[] BuildGray16 ()
        {
            var t = new byte [65536];
            for (int v = 0; v < 65536; v++) t [v] = ToSrgbByte (ToLinear ((ushort) v));
            return t;
        }

        private static float Lut (int i) => BitConverter.UInt32BitsToSingle (s_toLinear [i]);

        internal static float ToLinear (ushort v)
        {
            uint t = (uint) v * 0xff01u;
            int i = (int) (t >> 24), f = (int) ((t >> 8) & 0xffff);
            double d = Lut (i);
            if (f != 0) d = ((double) Lut (i + 1) - d) * (double) (uint) f * 1.52587890625e-05 + d;
            return (float) (d * 0.00392156862745098);
        }

        internal static byte ToSrgbByte (float s)
        {
            if (!(s > 0f)) return 0;
            if (s >= 1f) return 255;
            float x = s * 3354f;
            int i = (int) x;
            if ((float) i - x <= -0.5f) i++;
            return s_toSrgb [i];
        }
    }
